// The listing file's real shape (confirmed live 2026-08-06 by fetching the
// S3 object directly): { files: [...], paths: [...], truncated: bool } --
// NOT a bare array as AWS's own doc summary implied. files/paths entries are
// { filePath, modifiedTimestamp, size } for one level of DCG's remote
// directory (no recursion into subfolders).
//
// This n8n instance stores binary data on its own filesystem, not inlined
// as base64 on the item -- item.binary.data.data is just an internal mode
// marker (confirmed live 2026-08-07: it literally contains the string
// 'filesystem-v2', not the file bytes). Must use n8n's own binary-data
// helper, which resolves the reference correctly regardless of storage mode
// -- manual Buffer/base64 handling on item.binary.data.data does NOT work
// on this instance.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const result = JSON.parse(buffer.toString('utf-8'));
return [{ json: {
  fileCount: Array.isArray(result.files) ? result.files.length : null,
  pathCount: Array.isArray(result.paths) ? result.paths.length : null,
  truncated: result.truncated ?? null,
  files: result.files ?? [],
  paths: result.paths ?? [],
} }];
